    }
    final exactPlaces = _placements
        .where((placement) => placement.isExact)
        .map((placement) => placement.from);
    if (exactPlaces.toSet().length != exactPlaces.length) {
      throw ArgumentError(
        'Два Participant не могут иметь одинаковое exact place.',
      );
    }
  }

